import json, re, csv, sys
import numpy as np

INP = '/var/tmp/foundry-work/jit/jit-dev-kinetics-1/agent-claude-haiku-5-5/i016-interpreter-c34735/inputs.json'
D = json.load(open(INP))
docs = {x['doc_id']: x for x in D['documents']}
SETPOINT = {'C1': 20, 'C2': 42, 'C3': 42, 'C4': 20, 'C5': 30, 'C6': 42, 'C7': 42, 'C8': 37}
K_CONV = 1.0 / (60000 * 6.22e-3 * 0.52)   # mAU/min -> uM/s  (slope/194.06)

recs = {}   # id -> dict
def add(hv, cond, rep, S, v, src, T=None, flag='', note=''):
    assert hv not in recs, (hv, src)
    recs[hv] = dict(id=hv, cond=cond, rep=rep, S=S, v=v, src=src, T=T, flag=flag, note=note)

# ---- D3 Dara 2031-09-13 notebook (mAU/min, per-row conc units)
def dara_cond(h):
    if '7.40' in h: return 'C8'
    if 'no inhibitor' in h: return 'C8'      # Dara's own label correction (pH 7.4 set)
    if 'vehicle only' in h: return 'C4'
    if '303.15' in h: return 'C5'
    if 'deltazole 50' in h: return 'C7'
    raise ValueError(h)

ROW = re.compile(r'^([A-H]\d{2})\s+(HV-\d{4})\s+([\d.]+)\s*([mµμ]M)\s+(-?[\d.]+)\s+([\d.]+)\s*(\S*)\s*$')

def conc_uM(num, unit):
    return float(num) * (1000 if unit.startswith('m') else 1)

def parse_blocks(doc_id, cond_fn, unit_conv, src):
    cur = None
    overrides = {}
    for line in docs[doc_id]['text'].splitlines():
        if line.startswith('Plate ') or line.startswith('Plate '):
            cur = line
            continue
        m = ROW.match(line)
        if m and cur:
            well, hv, num, unit, val, T, flag = m.groups()
            cond, rep = cond_fn(cur)
            S = conc_uM(num, unit)
            add(hv, cond, rep, S, unit_conv(float(val)), src, T=float(T), flag=flag)
        # re-read lines (Dara, plate 5 A08)
        if line.strip().startswith('A08') and 're-read' not in line and 'slope' in line:
            mm = re.search(r'slope (-?[\d.]+) mAU/min', line)
            overrides['A08'] = float(mm.group(1))
    return overrides

def dara_rep(h):
    return int(re.search(r'Replicate (\d)', h).group(1))

def dara_cond_rep(h):
    return dara_cond(h), dara_rep(h)

# Dara: the plate 5 A08 re-read replaces the first reading (SOP sec 3)
ov = parse_blocks('D3', dara_cond_rep, lambda s: abs(s) * K_CONV, 'D3 Dara')
# apply re-read override for HV-0518 (plate 5 A08)
recs['HV-0518']['v'] = abs(ov['A08']) * K_CONV
# Dara block 'Plate 5 | Assay: pH 8.50 @ 303.15 K | Replicate 3' had no rep parse issue
# Dara's 'Plate 3 pH 8.50 @ 315.15 K (no inhibitor) | Replicate 1' -> C8 by her correction

# ---- D15 Ana 2031-09-19 notebook (mAU/min)
def ana_cond_rep(h):
    rep = dara_rep(h)
    if 'Plate 11' in h:
        return 'C2', rep      # addendum: vehicle only, deltazole never added
    if 'C6' in h:
        return 'C6', rep
    if 'C4' in h:
        return 'C4', rep
    raise ValueError(h)
parse_blocks('D15', ana_cond_rep, lambda s: abs(s) * K_CONV, 'D15 Ana')

# ---- D7 raw automatic export (already uM/s) -- overrides rate when id present
RAW = re.compile(r'^(\d+)\s+([A-G]\d{2})\s+(HV-\d{4})\s+([\d.]+)\s+([\d.]+)\s+(\d+)\s*(SAT|OVR|LOW)?\s*$')
raw = {}
for line in docs['D7']['text'].splitlines():
    m = RAW.match(line)
    if m:
        raw[m.group(3)] = dict(v=float(m.group(4)), flag=m.group(7) or '')
print('raw export wells:', len(raw), file=sys.stderr)

# ---- D8 Mikael CSV (S mM, rate uM/min)
def parse_num(s):
    s = s.strip()
    m = re.match(r'^([\d.]+)×10\^(-?\d+)$', s)
    if m:
        return float(m.group(1)) * 10 ** int(m.group(2))
    return float(s)

txt = docs['D8']['text'].split('```')[1]
rows = list(csv.reader(txt.strip().splitlines()))
for r in rows:
    if not r or not r[0].startswith(('HV-', 'BLK-', 'sample_id')):
        continue
    if r[0] == 'sample_id' or r[0].startswith('BLK-'):
        continue
    hv, plate, well, label, rep, S, rate, t0, qc = (r + [''] * 9)[:9]
    if 'deltazole 50' in label:
        cond = 'C7'
    elif 'deltazole 250' in label:
        cond = 'C6'
    elif '293.15' in label or '293.15' in label:
        cond = 'C1'
    elif 'pH 7.00' in label:
        cond = 'C3'
    else:
        raise ValueError(label)
    add(hv, cond, int(rep), parse_num(S) * 1000, parse_num(rate) / 60, 'D8 Mikael', flag=qc)

# ---- D12 Kofi PC export (decimal comma; rate nM/min after his correction; S uM)
lines = docs['D12']['text'].split('```')[1].strip().splitlines()
hdr = lines[0].split(';')
for ln in lines[1:]:
    f = ln.split(';')
    if len(f) < 8:
        continue
    hv, plate, well, label, rep, S, rate, remark = f[:8]
    if '303,15' in label:
        cond = 'C5'
    elif '315,15' in label and 'deltazole' in label:
        cond = 'C7'
    elif '293,15' in label and 'deltazole' in label:
        cond = 'C1'
    else:
        raise ValueError(label)
    S = float(S.replace(',', '.'))
    v = float(rate.replace(',', '.')) / 1000 / 60  # nM/min -> uM/s
    add(hv, cond, int(rep), S, v, 'D12 Kofi', flag=remark.strip())

# ---- D11 Hamid notebook (rates mM/min, S uM)
SEC = None
for line in docs['D11']['text'].splitlines():
    if line.startswith('### '):
        h = line
        if 'Plate 3, pH 7.4' in h:
            SEC = ('C8', 1)
        elif 'Plate 12, 30' in h:
            SEC = ('C5', 4)
        elif 'Plate 4, pH 7.0' in h:
            SEC = ('C3', 1)
        elif 'Plate 4, 20 °C' in h:
            SEC = ('C1', 3)
        else:
            SEC = None
        continue
    m = re.match(r'^\|\s*(HV-\d{4})\s*\|\s*(\w+)\s*\|\s*([\d.]+)\s*\|\s*([\d.e+-]+)\s*\|\s*(.*?)\s*\|\s*$', line)
    if m and SEC:
        hv, well, S, v, note = m.groups()
        add(hv, SEC[0], SEC[1], float(S), float(v) * 1000 / 60, 'D11 Hamid', note=note)

# ---- D14/D10/... none needed. Lin's bench log D13 (prose, rates in uM/s, S in nM)
LIN = {
  # plate 4, pH 8.5 303.15 K rep 1 -> C5
  'C5': (1, [('HV-0430', 500000, 0.4329), ('HV-0431', 120000, 0.2755), ('HV-0432', 20000, 0.08703),
             ('HV-0433', 1500000, 0.4691), ('HV-0434', 800000, 0.4916), ('HV-0435', 80000, 0.2259),
             ('HV-0436', 50000, 0.1651), ('HV-0437', 200000, 0.3304), ('HV-0438', 30000, 0.1206),
             ('HV-0439', 300000, 0.3831)]),
  # plate 10 B vehicle only, pH 8.5 315.15 K no inhibitor rep 4 -> C2
  'C2': (4, [('HV-0699', 200000, 0.1308), ('HV-0700', 1500000, 0.2277), ('HV-0701', 120000, 0.09123),
             ('HV-0702', 50000, 0.04994), ('HV-0703', 800000, 0.1849), ('HV-0704', 80000, 0.06892),
             ('HV-0705', 500000, 0.1707), ('HV-0706', 300000, 0.1476), ('HV-0707', 30000, 0.03305),
             ('HV-0708', 20000, 0.02160)]),
  # plate 13 pH 7.4 310.15 K rep 3 -> C8
  'C8r': (3, [('HV-0780', 20000, 0.06373), ('HV-0781', 30000, 0.08979), ('HV-0782', 50000, 0.1359),
              ('HV-0783', 80000, 0.1831), ('HV-0784', 120000, 0.2202), ('HV-0785', 200000, 0.3032),
              ('HV-0786', 300000, 0.3564), ('HV-0787', 500000, 0.3786), ('HV-0788', 800000, 0.4276),
              ('HV-0789', 1500000, 0.4797)]),
}
for key, (rep, items) in LIN.items():
    cond = 'C8' if key == 'C8r' else key
    for hv, S_nM, v in items:
        add(hv, cond, rep, S_nM / 1000, v, 'D13 Lin')
# plate 9 A (C2 rep 3) and plate 11 B (C7 rep 4): S from Lin, rate from raw export later
LIN_S_9 = [('HV-0648', 80000), ('HV-0649', 800000), ('HV-0650', 200000), ('HV-0651', 1500000),
           ('HV-0652', 120000), ('HV-0653', 500000), ('HV-0654', 50000), ('HV-0655', 300000),
           ('HV-0656', 30000), ('HV-0657', 20000)]
for hv, S_nM in LIN_S_9:
    add(hv, 'C2', 3, S_nM / 1000, None, 'D13 Lin (S) + D7', note='plate 9 A')
LIN_S_11 = [('HV-0729', 20000), ('HV-0730', 30000), ('HV-0731', 50000), ('HV-0732', 80000),
            ('HV-0733', 120000), ('HV-0734', 200000), ('HV-0735', 300000), ('HV-0736', 500000),
            ('HV-0737', 800000), ('HV-0738', 1500000)]
for hv, S_nM in LIN_S_11:
    add(hv, 'C7', 4, S_nM / 1000, None, 'D13 Lin (S) + D7', note='plate 11 B')

# ---- D2 Ruth summary (rates uM/min, S nM); C3 r4 (plate 8 A), C4 r2 (plate 9 B), C2 r2 (plate 5 E)
RUTH = {
  'C3': (4, [('HV-0634', 20000, 1.99), ('HV-0635', 30000, 2.81), ('HV-0636', 50000, 4.23),
             ('HV-0637', 80000, 5.77), ('HV-0638', 120000, 7.52), ('HV-0639', 200000, 10.5),
             ('HV-0640', 300000, 12.0), ('HV-0641', 500000, 14.6), ('HV-0642', 800000, 16.4),
             ('HV-0643', 1500000, 11.4)]),
  'C4': (2, [('HV-0673', 20000, 2.72), ('HV-0667', 30000, 3.70), ('HV-0668', 50000, 5.59),
             ('HV-0672', 80000, 8.24), ('HV-0666', 120000, 11.6), ('HV-0671', 200000, 14.7),
             ('HV-0674', 300000, 17.4), ('HV-0669', 500000, 20.1), ('HV-0670', 800000, 23.1),
             ('HV-0665', 1500000, 25.1)]),
  'C2': (2, [('HV-0588', 20000, 1.49), ('HV-0587', 30000, 1.92), ('HV-0580', 50000, 2.93),
             ('HV-0579', 80000, 4.35), ('HV-0586', 120000, 5.71), ('HV-0583', 200000, 7.28),
             ('HV-0585', 300000, 8.82), ('HV-0582', 500000, 10.4), ('HV-0581', 800000, 12.5),
             ('HV-0584', 1500000, 12.9)]),
}
for cond, (rep, items) in RUTH.items():
    for hv, S_nM, v in items:
        add(hv, cond, rep, S_nM / 1000, v / 60, 'D2 Ruth')
# C3 r2 (plate 4 G): S from Ruth's table, rate from raw export
RUTH_C3_R2 = [('HV-0492', 300), ('HV-0493', 80), ('HV-0494', 30), ('HV-0495', 120), ('HV-0496', 200),
              ('HV-0497', 500), ('HV-0498', 20), ('HV-0499', 1500), ('HV-0500', 800), ('HV-0501', 50)]
for hv, S in RUTH_C3_R2:
    add(hv, 'C3', 2, float(S), None, 'D2 Ruth (S) + D7', note='plate 4 G')

# ---- Apply raw automatic export values (SOP sec 1): these replace transcriptions
for hv, r in raw.items():
    if hv not in recs:
        raise SystemExit('raw well not in table: ' + hv)
    recs[hv]['v'] = r['v']
    recs[hv]['raw'] = True
    if r['flag']:
        recs[hv]['flag'] = (recs[hv]['flag'] + ' ' + r['flag']).strip()
    recs[hv]['src'] += ' +D7raw'

# ---- Label/unit corrections
# Kofi: substrate tubes swapped for HV-0473 and HV-0482 (both his own report)
recs['HV-0473']['S'], recs['HV-0482']['S'] = 1500.0, 20.0
# Dara: plate 3 E wells (pH 7.4) already mapped to C8 via her label correction
# Leila (master-mix log author): C3 (42 C, pH 7.0) mix was 1:250 -> halve all C3 rates
for hv, r in recs.items():
    if r['cond'] == 'C3':
        r['v'] = r['v'] * 0.5
        r['note'] = (r.get('note', '') + ' C3 rescaled x0.5 (1:250 mix)').strip()

# ---- Exclusions
manual = {
    'HV-0301': 'SAT (Dara; reader log) 2.1',
    'HV-0347': 'OVR (Hamid; reader log) 2.1',
    'HV-0359': 'substrate added 2 min late (Dara addendum) 2.3',
    'HV-0382': 'bubble during read (Kofi) 2.2',
    'HV-0404': 'bubble 09:26 during read 09:24-09:34 (Hamid) 2.2',
    'HV-0557': 'bubble present at read start (Mikael) 2.2',
    'HV-0643': 'bubble present at read start (Ruth) 2.2',
    'HV-0653': 'bubble 5 min before end of 12-min read (Lin) 2.2',
    'HV-0670': 'loading bubble cleared 2 min after read start (Ruth) 2.2',
