excl = {}
for hv, why in manual.items():
    excl[hv] = why
for hv, r in recs.items():
    if 'SAT' in r['flag'] or 'OVR' in r['flag']:
        excl.setdefault(hv, 'reader flag ' + r['flag'])
    if r['T'] is not None and abs(r['T'] - SETPOINT[r['cond']]) > 1.0:
        excl.setdefault(hv, 'block temp %.1f vs %s' % (r['T'], SETPOINT[r['cond']]))

# ---- Retained data and sanity dump
json.dump({'recs': recs, 'excl': excl}, open('/tmp/claude-0/-var-tmp-foundry-work-jit-jit-dev-kinetics-1-agent-claude-haiku-5-5-i016-interpreter-c34735/2fd91e72-59a0-4ccc-abf4-fc022200b393/scratchpad/recs.json', 'w'), indent=1, default=str)
print('total wells', len(recs), 'excluded', len(excl))
for k in sorted(excl):
