import json, numpy as np
d=json.load(open('/tmp/claude-0/-var-tmp-foundry-work-jit-jit-dev-kinetics-1-agent-claude-haiku-5-5-i016-interpreter-c34735/2fd91e72-59a0-4ccc-abf4-fc022200b393/scratchpad/recs.json'))
recs=d['recs']; excl=d['excl']
def data(c):
    rows=[(r['S'],r['v']) for k,r in recs.items() if r['cond']==c and k not in excl]
    a=np.array(rows); return a[:,0],a[:,1]
S6,v6=data('C6'); S7,v7=data('C7'); S2,v2=data('C2'); S1,v1=data('C1')
# grid search: Km0 (C2 fit 192) and joint Vm, Ki for C6 & C7
best=None
for Vm in np.linspace(0.20,0.34,141):
  for K0 in np.linspace(120,300,91):
    for Ki in np.geomspace(2,300,200):
      p6=Vm*S6/(K0*(1+250/Ki)+S6); p7=Vm*S7/(K0*(1+50/Ki)+S7)
      sse=np.sum((v6-p6)**2)+np.sum((v7-p7)**2)
      if best is None or sse<best[0]: best=(sse,Vm,K0,Ki)
print('joint C6+C7 competitive fit (Vm,K0,Ki):', best[1:], 'sse', best[0])
# separate-K fits for reference
def fitK(S,v,Vm):
    ks=np.geomspace(10,1e5,4000); s=[np.sum((v-Vm*S/(k+S))**2) for k in ks]; return ks[int(np.argmin(s))], min(s)
for Vm in [0.2426]:
    print('K6',fitK(S6,v6,Vm),'K7',fitK(S7,v7,Vm))

